import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import "./App.css";
import Menu2 from "./components/Menu2";
import Form from "./components/Form";
import Navbar from "./components/Navbar";
import Table from "./components/Table";
import History from "./components/History";
import FinalArea from "./components/FinalArea";

function App() {
  return (
    <Router>
      <div className="bg-gray-50 min-h-screen flex flex-col w-full">
        {/* Navbar at Full Width */}
        <Navbar />

        {/* Main Content Section */}
        <div className="w-full flex flex-col items-center px-4">
          <Routes>
            <Route path="/" element={<Form />} />
            <Route path="/table" element={<Table />} />
            <Route path="/final-area" element={<FinalArea />} />
            <Route path="/rss" element={<Menu2 Name="RSS" />} />
            <Route path="/top" element={<Menu2 Name="TOP" />} />
            <Route path="/pnr-overhead-summary" element={<Menu2 Name="Pnr Overhead Summary" />} />
            <Route path="/history" element={<History />} />
          </Routes>
        </div>

        {/* Navigation Buttons */}
        <div className="w-full bg-gray-200 mt-8 py-4">
          <div className="w-full max-w-7xl mx-auto bg-white shadow-md rounded-lg p-6 border">
            <div className="grid grid-cols-4 gap-4 text-center">
              <Link to="/rss" className="text-lg font-medium text-blue-600 hover:underline">RSS</Link>
              <Link to="/top" className="text-lg font-medium text-blue-600 hover:underline">TOP</Link>
              <Link to="/pnr-overhead-summary" className="text-lg font-medium text-blue-600 hover:underline">
                Pnr Overhead Summary
              </Link>
              <Link to="/history" className="text-lg font-medium text-blue-600 hover:underline">History</Link>
            </div>
          </div>
        </div>
      </div>
    </Router>
  );
}

export default App;
